function detectPlatform(): 'ios' | 'android' | 'desktop' {
  try { if (typeof navigator === 'undefined') return 'desktop'; const ua = navigator.userAgent || ''; if (/iPhone|iPad|iPod/i.test(ua)) return 'ios'; if (/Android/i.test(ua)) return 'android'; return 'desktop' } catch { return 'desktop' }
}

export function InstallAppDialog({ onClose }: { onClose: () => void }) {
  const { language } = useLanguage()
  const d = D[language] || D.en
  const [platform, setPlatform] = useState<'ios' | 'android' | 'desktop'>('desktop')
  const [installed, setInstalled] = useState(false)

  useEffect(() => {
    try { setPlatform(detectPlatform()); const standalone = window.matchMedia?.('(display-mode: standalone)').matches || (window.navigator as any).standalone === true; setInstalled(Boolean(standalone)) } catch {}
  }, [])

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 px-4" onClick={()=>{ try { onClose() } catch {} }}>
      <div className="w-full max-w-md rounded-2xl border border-border bg-card p-5 shadow-xl" onClick={(e) => e.stopPropagation()} role="dialog" aria-labelledby="install-dialog-title">
        <h2 id="install-dialog-title" className="font-display text-lg font-semibold">{d.title}</h2>
        <p className="mt-1 text-xs text-muted-foreground">{d.desc}</p>
        {installed && (<p className="mt-3 rounded-xl bg-green-50 px-3 py-2 text-xs text-green-800 dark:bg-green-950/40 dark:text-green-200">{d.already}</p>)}
        <div className="mt-4 flex gap-2 text-xs font-medium"><button onClick={() => setPlatform('ios')} className={`flex-1 rounded-full px-3 py-1.5 transition ${platform === 'ios'? 'bg-foreground text-background' : 'bg-secondary text-secondary-foreground'}`}>{d.iosBtn}</button><button onClick={() => setPlatform('android')} className={`flex-1 rounded-full px-3 py-1.5 transition ${platform === 'android'? 'bg-foreground text-background' : 'bg-secondary text-secondary-foreground'}`}>{d.androidBtn}</button><button onClick={() => setPlatform('desktop')} className={`flex-1 rounded-full px-3 py-1.5 transition ${platform === 'desktop'? 'bg-foreground text-background' : 'bg-secondary text-secondary-foreground'}`}>{d.desktopBtn}</button></div>
        <div className="mt-4 rounded-xl border border-border bg-background p-4 text-sm">
          {platform === 'ios' && (<ol className="list-decimal space-y-2 pl-5 text-foreground"><li dangerouslySetInnerHTML={{__html: d.ios1}} /><li dangerouslySetInnerHTML={{__html: d.ios2}} /><li dangerouslySetInnerHTML={{__html: d.ios3}} /><li dangerouslySetInnerHTML={{__html: d.ios4}} /></ol>)}
          {platform === 'android' && (<ol className="list-decimal space-y-2 pl-5 text-foreground"><li dangerouslySetInnerHTML={{__html: d.and1}} /><li dangerouslySetInnerHTML={{__html: d.and2}} /><li dangerouslySetInnerHTML={{__html: d.and3}} /><li dangerouslySetInnerHTML={{__html: d.and4}} /></ol>)}
          {platform === 'desktop' && (<ol className="list-decimal space-y-2 pl-5 text-foreground"><li dangerouslySetInnerHTML={{__html: d.desk1}} /><li dangerouslySetInnerHTML={{__html: d.desk2}} /><li dangerouslySetInnerHTML={{__html: d.desk3}} /></ol>)}
        </div>
        <p className="mt-3 text-xs text-muted-foreground">{d.footer}</p>
        <div className="mt-5 flex justify-end"><button onClick={()=>{ try { onClose() } catch {} }} className="rounded-full border border-border px-4 py-2 text-sm hover:bg-secondary">{d.got}</button></div>
      </div>
    </div>
  )
}
